7668	function renderConversationRecord(norm) {
7669	  // Engine step events — render the raw event chip + the default-expanded
7670	  // step report card. Not a chat turn; bypasses the role-based bubble path.
7671	  if (norm.kind === "step_completed" || norm.kind === "step_failed") {
7672	    return renderStepEventRecord(norm);
7673	  }
7674	
7675	  // Step started / step status — a lightweight status row (text + icon). No
7676	  // report card, no fold / raw / chip: it is just the step region's lifecycle
7677	  // anchor. `step_started` marks RUNNING ("进行中"); `step_status` marks a
7678	  // non-terminal SETTLED state ("已暂停" / "重试中"). Both group under the same
7679	  // stepKey as the step's other records, so the region appears the instant the
7680	  // step starts (vital for non-LLM steps) and updates in place as it pauses.
7681	  if (norm.kind === "step_started" || norm.kind === "step_status") {
7682	    return renderStepStartedRecord(norm);
7683	  }
7684	
7685	  // Non-terminal step usage events — render a lightweight usage-only chip
7686	  // (not a full report card, since the step hasn't completed). Shows the
7687	  // step's token usage so the user sees self_check / verify_spec / test
7688	  // usage even when they return REVISION_NEEDED and are abandoned in the
7689	  // fix loop. The chip is collapsed by default; expand to see usage detail.
7690	  if (norm.kind === "step_output") {
7691	    return renderStepOutputUsageRecord(norm);
7692	  }
7693	
7694	  // Per-group DAG status — a lightweight, self-contained marker (not a chat
7695	  // turn, no fold/raw affordances) inserted into the implement step's time
7696	  // line so the user watches G1–G5 progress while the parallel step runs.
7697	  if (norm.kind === "group_status") {
7698	    return renderGroupStatusRecord(norm);
7699	  }
7700	
7701	  const known = ["user", "assistant", "system"].includes(norm.role);
7702	  const role = known ? norm.role : "other";
7703	  const content = typeof norm.content === "string" ? norm.content : "";
7704	
7705	  // user role with a template/user-content marker: a default-collapsed chip
7706	  // for the boilerplate prefix + a default-expanded bubble for the actual
7707	  // task content. Falls through to the legacy whole-chip path when there is
7708	  // no marker (older / non-step prompts).
7709	  if (norm.role === "user" && content) {
7710	    const split = splitUserPromptByMarker(content);
7711	    if (split) return renderUserMarkerRecord(norm, split);
